-- Запись журнала «Новости платформы»: посадочные «категория + семейство модели» (01.10.2026).
INSERT INTO "PlatformNews" ("id", "title", "body", "publishedAt", "updatedAt") VALUES
    ('news_20261001_model_landings',
     'На сайте появились страницы «раздел + модель»: сиденья для Ford Transit, ГАЗель Next и других',
     'У каждой модели (семейства) теперь есть страницы по разделам каталога: например, «Сиденья для ГАЗель Next» или «Комплектующие для сидений Mercedes Sprinter». Адрес — как у страницы модели с добавлением раздела: /modeli/gazel-next/sidenja-i-komplektuyshie. Такая страница создаётся сама, когда в разделе набирается не меньше трёх товаров, подходящих модели.

Поэтому важно, чтобы у товаров была отмечена совместимость («Товары → Разбор совместимости»): без неё товар не попадёт ни на страницу модели, ни на страницу «раздел + модель». Ссылки на эти страницы показываются на странице модели, они же попадают в карту сайта для поисковиков.',
     '2026-10-01 14:00:00', CURRENT_TIMESTAMP)
ON CONFLICT ("id") DO NOTHING;
